#### 3. Module 1: Intersection Vehicle Sensor Ingester

Tracks vehicle lane queues thread-safely using lock-free atomic concurrency operations.

```csharp
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using AutonomousTrafficControl.Domain;
using AutonomousTrafficControl.Interfaces;

namespace AutonomousTrafficControl.Modules
{
    public class SensorIngester : ISensorIngester
    {
        private readonly ConcurrentDictionary<LaneDirection, int> _laneQueues = new();

        public SensorIngester()
        {
            // Initialize all lanes to zero vehicles
            foreach (LaneDirection direction in Enum.GetValues(typeof(LaneDirection)))
            {
                _laneQueues[direction] = 0;
            }
        }

        public void RecordArrival(LaneDirection direction, int count = 1)
        {
            if (count < 0) throw new ArgumentException("Arrival count cannot be negative.");
            _laneQueues.AddOrUpdate(direction, count, (_, current) => current + count);
        }

        public void RecordDeparture(LaneDirection direction, int count = 1)
        {
            if (count < 0) throw new ArgumentException("Departure count cannot be negative.");
            _laneQueues.AddOrUpdate(direction, 0, (_, current) => Math.Max(0, current - count));
        }

        public int GetQueueLength(LaneDirection direction)
        {
            return _laneQueues.TryGetValue(direction, out var count) ? count : 0;
        }

        public IReadOnlyDictionary<LaneDirection, int> GetAllQueues()
        {
            return new Dictionary<LaneDirection, int>(_laneQueues);
        }
    }
}
```

#### 4. Module 2: Adaptive Timing Optimization Engine

Uses queue length heuristics to scale green light times dynamically while guaranteeing strict bounds.

```csharp
using System;
using System.Collections.Generic;
using AutonomousTrafficControl.Domain;
using AutonomousTrafficControl.Interfaces;

namespace AutonomousTrafficControl.Modules
{
    public class AdaptiveTimingOptimizer : ITimingOptimizer
    {
        private readonly TimeSpan _minGreen;
        private readonly TimeSpan _maxGreen;
        private readonly TimeSpan _yellowDuration;
        private readonly TimeSpan _secondsPerVehicle;

        public AdaptiveTimingOptimizer(
            TimeSpan minGreen, 
            TimeSpan maxGreen, 
            TimeSpan yellowDuration, 
            TimeSpan secondsPerVehicle)
        {
            _minGreen = minGreen;
            _maxGreen = maxGreen;
            _yellowDuration = yellowDuration;
            _secondsPerVehicle = secondsPerVehicle;
        }

        public TimingParameters CalculateTiming(IReadOnlyDictionary<LaneDirection, int> queues, IntersectionPhase nextPhase)
        {
            // Gather queues belonging to the active target phase
            int criticalQueue = nextPhase switch
            {
                IntersectionPhase.NorthSouth => Math.Max(
                    queues.GetValueOrDefault(LaneDirection.Northbound, 0),
                    queues.GetValueOrDefault(LaneDirection.Southbound, 0)
                ),
                IntersectionPhase.EastWest => Math.Max(
                    queues.GetValueOrDefault(LaneDirection.Eastbound, 0),
                    queues.GetValueOrDefault(LaneDirection.Westbound, 0)
                ),
                _ => throw new ArgumentOutOfRangeException(nameof(nextPhase))
            };

            // Heuristic calculation: Green Time scales linearly with vehicle wait lists
            double calculatedSeconds = criticalQueue * _secondsPerVehicle.TotalSeconds;

            TimeSpan adjustedGreen = TimeSpan.FromSeconds(calculatedSeconds);

            // Enforce minimum and maximum hardware tolerances
            if (adjustedGreen < _minGreen) adjustedGreen = _minGreen;
            if (adjustedGreen > _maxGreen) adjustedGreen = _maxGreen;

            return new TimingParameters(adjustedGreen, _yellowDuration);
        }
    }
}
```

#### 5. Module 3: Hardware Signal Controller

Simulates dispatch registers. It protects intersection safety invariants asynchronously, preventing illegal states (e.g., green-green conflicts) by forcing strict sequencing through state-machine rules.

```csharp
using System;
using System.Threading;
using System.Threading.Tasks;
using AutonomousTrafficControl.Domain;
using AutonomousTrafficControl.Interfaces;

namespace AutonomousTrafficControl.Modules
{
    public class HardwareSignalController : IHardwareController
    {
        private SignalColor _northSouthSignal = SignalColor.Red;
        private SignalColor _eastWestSignal = SignalColor.Red;
        private readonly object _stateLock = new();

        // 1-second All-Red period to clear intersection intersection completely
        private static readonly TimeSpan AllRedClearance = TimeSpan.FromSeconds(1);

        public (SignalColor NorthSouth, SignalColor EastWest) GetHardwareState()
        {
            lock (_stateLock)
            {
                return (_northSouthSignal, _eastWestSignal);
            }
        }

        public async Task TransitionToPhaseAsync(
            IntersectionPhase targetPhase, 
            TimeSpan greenDuration, 
            TimeSpan yellowDuration, 
            CancellationToken cancellationToken)
        {
            // Transition Safe Sequence Logic
            if (targetPhase == IntersectionPhase.NorthSouth)
            {
                // Safety invariant step 1: Warn and drop East-West down to Yellow
                UpdateHardwareState(SignalColor.Green, SignalColor.Yellow);
                await SafeDelay(yellowDuration, cancellationToken);

                // Safety invariant step 2: Enter all-red boundary
                UpdateHardwareState(SignalColor.Red, SignalColor.Red);
                await SafeDelay(AllRedClearance, cancellationToken);

                // Safety invariant step 3: Secure green channel to North-South
                UpdateHardwareState(SignalColor.Green, SignalColor.Red);
                await SafeDelay(greenDuration, cancellationToken);
            }
            else // EastWest
            {
                // Safety invariant step 1: Warn and drop North-South down to Yellow
                UpdateHardwareState(SignalColor.Yellow, SignalColor.Green);
                await SafeDelay(yellowDuration, cancellationToken);

                // Safety invariant step 2: Enter all-red boundary
                UpdateHardwareState(SignalColor.Red, SignalColor.Red);
                await SafeDelay(AllRedClearance, cancellationToken);

                // Safety invariant step 3: Secure green channel to East-West
                UpdateHardwareState(SignalColor.Red, SignalColor.Green);
                await SafeDelay(greenDuration, cancellationToken);
            }
        }

        private void UpdateHardwareState(SignalColor ns, SignalColor ew)
        {
            // Prevent dangerous illegal combinations physically
            if (ns == SignalColor.Green && ew == SignalColor.Green)
            {
                throw new InvalidOperationException("CRITICAL HARDWARE FAILURE: Green state conflict detected in both routes!");
            }

            lock (_stateLock)
            {
                _northSouthSignal = ns;
                _eastWestSignal = ew;
            }
        }

        private static async Task SafeDelay(TimeSpan duration, CancellationToken cancellationToken)
        {
            try
            {
                await Task.Delay(duration, cancellationToken);
            }
            catch (TaskCanceledException)
            {
                // Hardware shutdown or cycle override signal dispatched
            }
        }
    }
}
```

#### 6. Orchestrator Loop

Coordinates the modules, continuously evaluating intersection cycles, polling telemetry queues, applying calculations, and instructing physical execution.

```csharp
using System;
using System.Threading;
using System.Threading.Tasks;
using AutonomousTrafficControl.Domain;
using AutonomousTrafficControl.Interfaces;

namespace AutonomousTrafficControl.Orchestration
{
    public class TrafficIntersectionOrchestrator
    {
        private readonly ISensorIngester _ingester;
        private readonly ITimingOptimizer _optimizer;
        private readonly IHardwareController _hardwareController;
        private IntersectionPhase _currentPhase = IntersectionPhase.NorthSouth;

        public TrafficIntersectionOrchestrator(
            ISensorIngester ingester, 
            ITimingOptimizer optimizer, 
            IHardwareController hardwareController)
        {
            _ingester = ingester;
            _optimizer = optimizer;
            _hardwareController = hardwareController;
        }

        public async Task StartLoopAsync(CancellationToken cancellationToken)
        {
            Console.WriteLine("[ORCHESTRATOR] Initializing autonomous dynamic cycle loops...");

            while (!cancellationToken.IsCancellationRequested)
            {
                // Read snapshot queue lengths
                var currentQueues = _ingester.GetAllQueues();

                // Rotate targets safely
                IntersectionPhase nextPhase = _currentPhase == IntersectionPhase.NorthSouth 
                    ? IntersectionPhase.EastWest 
                    : IntersectionPhase.NorthSouth;

                // Determine dynamic signal cycle window length
                TimingParameters optimalTiming = _optimizer.CalculateTiming(currentQueues, nextPhase);

                Console.WriteLine($"\n[ORCHESTRATOR] Cycle Decided: {nextPhase}");
                Console.WriteLine($" -> Optimizing Green window: {optimalTiming.GreenDuration.TotalSeconds:F1}s (Based on vehicle queues)");

                // Execute safe transition protocol
                await _hardwareController.TransitionToPhaseAsync(
                    nextPhase, 
                    optimalTiming.GreenDuration, 
                    optimalTiming.YellowDuration, 
                    cancellationToken
                );

                _currentPhase = nextPhase;
            }
        }
    }
}
