### Demonstration Simulation

This dynamic CLI environment models real-world traffic patterns. It handles vehicle arrivals on background channels and models physics-accurate vehicle discharge rates (drainage) synchronized with green/red states.

```csharp
using System;
using System.Threading;
using System.Threading.Tasks;
using AutonomousTrafficControl.Domain;
using AutonomousTrafficControl.Interfaces;
using AutonomousTrafficControl.Modules;
using AutonomousTrafficControl.Orchestration;

namespace AutonomousTrafficControl
{
    internal class Program
    {
        private static async Task Main(string[] args)
        {
            Console.OutputEncoding = System.Text.Encoding.UTF8;
            Console.WriteLine("==========================================================");
            Console.WriteLine("     MODULAR AUTONOMOUS TRAFFIC LIGHT CONTROL SYSTEM     ");
            Console.WriteLine("==========================================================\n");

            using var cts = new CancellationTokenSource();

            // Module instantiations
            ISensorIngester sensorIngester = new SensorIngester();
            ITimingOptimizer optimizer = new AdaptiveTimingOptimizer(
                minGreen: TimeSpan.FromSeconds(3),
                maxGreen: TimeSpan.FromSeconds(10),
                yellowDuration: TimeSpan.FromSeconds(2),
                secondsPerVehicle: TimeSpan.FromSeconds(1)
            );
            IHardwareController hardwareController = new HardwareSignalController();

            var orchestrator = new TrafficIntersectionOrchestrator(sensorIngester, optimizer, hardwareController);

            // Mock load initially
            sensorIngester.RecordArrival(LaneDirection.Northbound, 8);
            sensorIngester.RecordArrival(LaneDirection.Southbound, 4);
            sensorIngester.RecordArrival(LaneDirection.Eastbound, 1);
            sensorIngester.RecordArrival(LaneDirection.Westbound, 2);

            // Fire and Forget asynchronous Tasks modeling environmental dynamics
            Task simulationTask = RunEnvironmentSimulationAsync(sensorIngester, cts.Token);
            Task dischargeTask = RunTrafficDischargeSimulationAsync(sensorIngester, hardwareController, cts.Token);
            Task displayTask = RunTelemetryOutputConsoleDashboardAsync(sensorIngester, hardwareController, cts.Token);

            // Execute master scheduler loop
            Task orchestratorTask = orchestrator.StartLoopAsync(cts.Token);

            Console.WriteLine("Traffic system online. Press [ENTER] key to exit simulation loop.");
            Console.ReadLine();

            // Stop system cleanly
            cts.Cancel();

            try
            {
                await Task.WhenAll(orchestratorTask, simulationTask, dischargeTask, displayTask);
            }
            catch (Exception ex) when (ex is OperationCanceledException or TaskCanceledException)
            {
                // Soft clean shutdown hook
            }

            Console.WriteLine("[SYSTEM] Clean shutdown completed.");
        }

        // Simulates unpredictable dynamic vehicle arrivals
        private static async Task RunEnvironmentSimulationAsync(ISensorIngester ingester, CancellationToken ct)
        {
            var random = new Random();
            while (!ct.IsCancellationRequested)
            {
                await Task.Delay(random.Next(800, 2500), ct);
                var directions = (LaneDirection[])Enum.GetValues(typeof(LaneDirection));
                var randomDirection = directions[random.Next(directions.Length)];

                ingester.RecordArrival(randomDirection, random.Next(1, 3));
            }
        }

        // Simulates lanes discharging vehicles dynamically when their physical lights are green
        private static async Task RunTrafficDischargeSimulationAsync(
            ISensorIngester ingester, 
            IHardwareController hardware, 
            CancellationToken ct)
        {
            while (!ct.IsCancellationRequested)
            {
                await Task.Delay(1000, ct); // Standard discharge interval (e.g., 1 car leaves per second under Green)
                var (nsState, ewState) = hardware.GetHardwareState();

                if (nsState == SignalColor.Green)
                {
                    ingester.RecordDeparture(LaneDirection.Northbound, 1);
                    ingester.RecordDeparture(LaneDirection.Southbound, 1);
                }
                if (ewState == SignalColor.Green)
                {
                    ingester.RecordDeparture(LaneDirection.Eastbound, 1);
                    ingester.RecordDeparture(LaneDirection.Westbound, 1);
                }
            }
        }

        // Live Dashboard Output Render
        private static async Task RunTelemetryOutputConsoleDashboardAsync(
            ISensorIngester ingester, 
            IHardwareController hardware, 
            CancellationToken ct)
        {
            while (!ct.IsCancellationRequested)
            {
                await Task.Delay(400, ct);
                var queues = ingester.GetAllQueues();
                var (ns, ew) = hardware.GetHardwareState();

                Console.Clear();
                Console.WriteLine("=======================================================================");
                Console.WriteLine("               INTELLIGENT INTERSECTION TELEMETRY MONITOR              ");
                Console.WriteLine("=======================================================================");
                Console.Write(" [NS SIGNAL STATE]: ");
                WriteSignalColorText(ns);
                Console.Write("   |   [EW SIGNAL STATE]: ");
                WriteSignalColorText(ew);
                Console.WriteLine();
                Console.WriteLine("-----------------------------------------------------------------------");
                Console.WriteLine("  Lanes & Waiting Queue Configurations: ");
                Console.WriteLine($"   ▲ NORTHBOUND: [Queue Size: {queues[LaneDirection.Northbound], 2} waiting]");
                Console.WriteLine($"   ▼ SOUTHBOUND: [Queue Size: {queues[LaneDirection.Southbound], 2} waiting]");
                Console.WriteLine($"   ▶ EASTBOUND:  [Queue Size: {queues[LaneDirection.Eastbound],  2} waiting]");
                Console.WriteLine($"   ◀ WESTBOUND:  [Queue Size: {queues[LaneDirection.Westbound],  2} waiting]");
                Console.WriteLine("=======================================================================");
                Console.WriteLine("Press [ENTER] at any time to turn off the traffic signal controls.");
            }
        }

        private static void WriteSignalColorText(SignalColor color)
        {
            var oldColor = Console.ForegroundColor;
            Console.ForegroundColor = color switch
            {
                SignalColor.Red => ConsoleColor.Red,
                SignalColor.Yellow => ConsoleColor.Yellow,
                SignalColor.Green => ConsoleColor.Green,
                _ => oldColor
            };
            Console.Write($"[{color.ToString().ToUpper()}]");
            Console.ForegroundColor = oldColor;
        }
    }
}
